        <div class="col-12 row justify-end">
          <div class="col-1">
            <q-checkbox v-model="concordo" />
          </div>
          <div class="col-11 q-px-md text-black">
            Eu li e aceito os Termos de Uso e a Política de Privacidade
          </div>
          <div class="col-12 q-py-md">
            <q-btn
              class="full-width"
              color="primary"
              label="Avançar"
              :disable="!concordo"
              @click="avancar()"
              dense
              no-caps
            />
          </div>
        </div>
      </div>
